<?php
/**
 * Antalya POS Order Delete Handler
 *
 * @package Antalya_POS
 * @since 6.4
 */

if (!defined('ABSPATH')) {
    exit;
}

/**
 * Handle Secure Order Deletion with Capability & Nonce Verification
 */
function rtpos_handle_order_delete($orders_table) {
    if (!current_user_can('manage_options')) {
        wp_die(esc_html__('You do not have sufficient permissions to perform this action.', 'antalya-pos'));
    }

    $order_id = isset($_GET['delete_order']) ? intval($_GET['delete_order']) : 0;
    if ($order_id <= 0) {
        return;
    }

    // Verify CSRF nonce generated by wp_nonce_url() in order-list.php
    check_admin_referer('rtpos_delete_order_' . $order_id);

    global $wpdb;
    $svg_check = '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"></polyline></svg>';

    $deleted = $wpdb->delete(
        $orders_table,
        ['id' => $order_id],
        ['%d']
    );

    if ($deleted !== false) {
        echo '<div class="apos-alert ord-alert-flex">' . $svg_check . '<span>' . sprintf(
            /* translators: %d: order ID */
            esc_html__('Order #%d deleted permanently!', 'antalya-pos'),
            $order_id
        ) . '</span></div>';
    }
}